corr_rating_ratingcount = round(df_valid['rating'].corr(df_valid['rating_count']), 3)
corr_price_rating = round(df_valid['actual_price'].corr(df_valid['rating']), 3)
corr_price_discount = round(df_valid['actual_price'].corr(df_valid['discount_percentage']), 3)

# Price segment analysis
price_bins = [0, 500, 1000, 2000, 5000, 10000, 200000]
price_labels = ['Under ₹500', '₹500-1K', '₹1K-2K', '₹2K-5K', '₹5K-10K', 'Over ₹10K']
