price_seg_stats['avg_rating'] = price_seg_stats['avg_rating'].round(2)
price_seg_stats['avg_discount_pct'] = price_seg_stats['avg_discount_pct'].round(1)
price_seg_stats['avg_rating_count'] = price_seg_stats['avg_rating_count'].round(0)

