# Rating distribution
rating_dist = df_valid['rating'].value_counts().sort_index().reset_index()
rating_dist.columns = ['rating', 'count']

# Rating buckets
def rating_bucket(r):
    if r >= 4.5: return '4.5-5.0 (Excellent)'
    elif r >= 4.0: return '4.0-4.4 (Good)'
    elif r >= 3.5: return '3.5-3.9 (Average)'
    elif r >= 3.0: return '3.0-3.4 (Below Avg)'
    else: return 'Below 3.0 (Poor)'

df_valid['rating_bucket'] = df_valid['rating'].apply(rating_bucket)
bucket_dist = df_valid['rating_bucket'].value_counts().reset_index()
bucket_dist.columns = ['bucket', 'count']
bucket_order = ['4.5-5.0 (Excellent)', '4.0-4.4 (Good)', '3.5-3.9 (Average)', '3.0-3.4 (Below Avg)', 'Below 3.0 (Poor)']
bucket_dist['bucket'] = pd.Categorical(bucket_dist['bucket'], categories=bucket_order, ordered=True)
bucket_dist = bucket_dist.sort_values('bucket')

# Top engaged products
top_engaged = df_valid.nlargest(10, 'rating_count')[['product_name', 'rating', 'rating_count', 'discounted_price', 'actual_price', 'discount_percentage', 'top_category']].reset_index(drop=True)
top_engaged['rating_count'] = top_engaged['rating_count'].astype(int)

# ─── 6. Review Sentiment Analysis ───────────────────────────────────────────

positive_words = Counter()
negative_words = Counter()

pos_terms = ['good', 'great', 'excellent', 'amazing', 'awesome', 'best', 'love', 'perfect', 'nice', 'fantastic', 'super', 'value for money', 'worth', 'satisfied', 'happy', 'quality', 'durable', 'fast', 'easy', 'comfortable', 'recommend', 'brilliant', 'wonderful', 'superb', 'outstanding', 'reliable']
neg_terms = ['bad', 'poor', 'worst', 'waste', 'terrible', 'horrible', 'disappointed', 'not working', 'stopped', 'broke', 'cheap', 'slow', 'difficult', 'defective', 'return', 'refund', 'damaged', 'useless', 'pathetic', 'regret', 'overpriced', 'fake', 'misleading', 'fragile', 'heating']

all_reviews = df_valid['review_title'].dropna().tolist() + df_valid['review_content'].dropna().tolist()
review_text = ' '.join(str(r).lower() for r in all_reviews)
review_words = re.findall(r'\b\w+\b', review_text)

for term in pos_terms:
    count = len(re.findall(r'\b' + re.escape(term) + r'\b', review_text))
    if count > 0:
        positive_words[term] = count

for term in neg_terms:
