top_positive = positive_words.most_common(12)
top_negative = negative_words.most_common(12)

# ─── 7. Strategic Recommendations ───────────────────────────────────────────

# Calculate data points for recommendations
high_discount_low_rating = df_valid[(df_valid['discount_percentage'] >= 50) & (df_valid['rating'] < 3.5)]
low_discount_high_rating = df_valid[(df_valid['discount_percentage'] <= 20) & (df_valid['rating'] >= 4.2)]
