discount_avg_rating_counts = [float(x) for x in discount_rating['avg_rating_count'].tolist()]
discount_product_counts = discount_rating['product_count'].tolist()

price_labels_chart = [str(l) for l in price_seg_stats['price_segment'].tolist()]
price_avg_ratings = price_seg_stats['avg_rating'].tolist()
price_avg_discounts = price_seg_stats['avg_discount_pct'].tolist()
price_product_counts = price_seg_stats['product_count'].tolist()

bucket_labels = [esc(b) for b in bucket_dist['bucket'].tolist()]
bucket_counts = bucket_dist['count'].tolist()

# Scatter data for discount vs rating
scatter_sample = df_valid.sample(min(300, len(df_valid)), random_state=42)
scatter_x = scatter_sample['discount_percentage'].tolist()
scatter_y = scatter_sample['rating'].tolist()
