price_bins = [0, 500, 1000, 2000, 5000, 10000, 200000]
price_labels = ['Under ₹500', '₹500-1K', '₹1K-2K', '₹2K-5K', '₹5K-10K', 'Over ₹10K']
df_valid['price_segment'] = pd.cut(df_valid['discounted_price'], bins=price_bins, labels=price_labels, include_lowest=True)

price_seg_stats = df_valid.groupby('price_segment', observed=True).agg(
