positive_words = Counter()
negative_words = Counter()

pos_terms = ['good', 'great', 'excellent', 'amazing', 'awesome', 'best', 'love', 'perfect', 'nice', 'fantastic', 'super', 'value for money', 'worth', 'satisfied', 'happy', 'quality', 'durable', 'fast', 'easy', 'comfortable', 'recommend', 'brilliant', 'wonderful', 'superb', 'outstanding', 'reliable']
neg_terms = ['bad', 'poor', 'worst', 'waste', 'terrible', 'horrible', 'disappointed', 'not working', 'stopped', 'broke', 'cheap', 'slow', 'difficult', 'defective', 'return', 'refund', 'damaged', 'useless', 'pathetic', 'regret', 'overpriced', 'fake', 'misleading', 'fragile', 'heating']

all_reviews = df_valid['review_title'].dropna().tolist() + df_valid['review_content'].dropna().tolist()
review_text = ' '.join(str(r).lower() for r in all_reviews)
review_words = re.findall(r'\b\w+\b', review_text)

for term in pos_terms:
