from html.parser import HTMLParser

class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.open_tags = []
        self.void_elements = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.open_tags.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.open_tags and self.open_tags[-1] == tag:
            self.open_tags.pop()
        else:
            self.errors.append(f'Mismatched tag: </{tag}>')

with open('/app/output/final_report.html', 'r') as f:
    content = f.read()

v = HTMLValidator()
v.feed(content)
if v.errors:
    print('HTML validation issues:')
    for e in v.errors[:10]:
        print(f'  {e}')
else:
    print('HTML structure looks valid')
print(f'Remaining open tags: {v.open_tags[-5:] if v.open_tags else \"none\"}')
print(f'File size: {len(content):,} bytes')
"

